/* FoxiOra — local-first shift scheduler. Sections: STORAGE · PARSER · SCHEDULE/CONFLICTS · UI.
   Times are stored as epoch-ms segments, so old shifts keep their real times if a code is later edited. */
const $=s=>document.querySelector(s), DAY=864e5;
const DEF=[['N','Night','19:30-08:00'],['D','Morning','07:30-14:30'],['E','Evening','14:00-20:00'],['n','Short night','20:00-24:00'],['M','Leave','leave'],['S','Sick leave','leave'],['OFF','Day off','off'],['*','Day off','off'],['-','Day off','off']];
const VER='v12.8';
const bootStarted=Date.now();
const DEFAULT_COMBOS=['DE','EN','En'];
const DS=()=>({wps:[],shifts:[],events:[],mates:[],gap:120,cal:'j',theme:'auto',lang:'fa',ver:3,myname:'',h24:true,fdow:6,cross:true,same:false,fh:2,weekend:[5],holidays:true,learnOCR:true,themePlaces:true,rosterDays:{},ocrMemory:{version:1,glyphs:[],names:[]}});
let S=DS(),tab='today',cm=new Date(),sel='',vm='month';

/* ---------- STORAGE (IndexedDB, one state object; swap later for per-table stores) ---------- */
const db=()=>new Promise((r,j)=>{const q=indexedDB.open('shiftfox',1);q.onupgradeneeded=()=>q.result.createObjectStore('kv');q.onsuccess=()=>r(q.result);q.onerror=j});
async function load(){const d=await db();return new Promise(r=>{const q=d.transaction('kv').objectStore('kv').get('state');q.onsuccess=()=>r(q.result)})}
async function save(){const d=await db();d.transaction('kv','readwrite').objectStore('kv').put(S,'state')}

/* ---------- SHIFT CODES ---------- */
// Text format per line: code|label|HH:MM-HH:MM  or  code|label|leave  or  code|label|off
const encCodes=cs=>cs.map(c=>`${c.code}|${c.label}|${c.type==='work'?c.start+'-'+c.end:c.type}`).join('\n');
function decCodes(t){t=nrm(t);return t.split('\n').map(l=>l.split('|').map(x=>x.trim())).filter(a=>a[0]).map(([code,label,v=''])=>{
  const m=v.match(/^(\d{1,2}:\d{2})-(\d{1,2}:\d{2})$/);return m?{code,label,type:'work',start:m[1],end:m[2]}:{code,label,type:v==='off'?'off':'leave'}})}
// Longest-match-first tokenizer: "DEn" -> D,E,n ; "N" never becomes "n" (case-sensitive).
function parse(wp,text){if(!wp?.codes||!text)return null;text=nrm(text).replace(/[–—−]/g,'-');
 const tokens=wp.codes.flatMap(c=>[{token:c.code,c},...(c.aliases||[]).map(token=>({token,c}))]).filter(x=>x.token).sort((a,b)=>b.token.length-a.token.length);
 if(/^[-]+$/.test(text)&&!wp.codes.some(c=>c.code==='-'&&c.type!=='off')){const off=wp.codes.find(c=>c.type==='off');return off?[{...off,code:offCode(wp)}]:null}
 // Explicit hospital definitions take precedence over built-in off aliases.
 if(!tokens.some(x=>x.token===text)&&/^(off|\*)$/i.test(text)){const c=wp.codes.find(c=>c.type==='off');if(c)return[{...c,code:offCode(wp)}]}
 let i=0,out=[];while(i<text.length){const matches=tokens.filter(x=>text.startsWith(x.token,i)),m=matches[0];if(!m)return null;
 if(matches.some(x=>x.token===m.token&&x.c.code!==m.c.code))return null;out.push(m.c);i+=m.token.length}return out.length?out:null}
const canonicalShift=(w,t)=>{const c=parse(w,t);return c?c.every(x=>x.type==='off')?offCode(w):c.map(x=>x.code).join(''):t};
const codeTokens=w=>[...new Set(w.codes.flatMap(c=>[c.code,...(c.aliases||[])]).join('')+'-م')].join('');
const shiftKind=(w,t)=>{const c=parse(w,t);return !c?'unknown':c.every(x=>x.type==='off')?'off':c.every(x=>x.type==='leave')?'leave':c.some(x=>x.code==='N'||x.code==='n')?'night':c.length>1?'combined':c.some(x=>x.code==='E')?'evening':'day'};
const shiftMark=(w,t)=>`<em class="shift-mark ${shiftKind(w,t)}">${codeHTML(canonicalShift(w,t))}</em>`;
const at=(d,t)=>{const[h,m]=t.split(':');const[y,mo,da]=d.split('-');return new Date(+y,mo-1,+da,+h,+m).getTime()};
function makeSegs(date,codes){return codes.filter(c=>c.type==='work').map(c=>{const s=at(date,c.start);let e=at(date,c.end);if(e<=s)e+=DAY;return{s,e,code:c.code}})}

/* ---------- SCHEDULE / CONFLICT ENGINE ---------- */
const segs=()=>S.shifts.flatMap(h=>h.segs.map(g=>({...g,wp:h.wp,sh:h.id}))).sort((a,b)=>a.s-b.s);
function issues(){const out=[],active=[];let latest=null;for(const g of segs()){
 for(let i=active.length-1;i>=0;i--)if(active[i].e<=g.s)active.splice(i,1);
 // A handover overlap within one workplace is continuous duty, not double booking.
 if(S.cross)for(const a of active)if(a.wp!==g.wp)out.push({t:'o',a,b:g,min:(Math.min(a.e,g.e)-g.s)/6e4});
 if(latest&&g.s>=latest.e&&(g.s-latest.e)/6e4<S.gap&&latest.sh!==g.sh)out.push({t:'g',a:latest,b:g,min:(g.s-latest.e)/6e4});
 if(!latest||g.e>latest.e)latest=g;active.push(g)}return out}
// The Today card follows a continuous combined duty until its final end time.
function displaySegs(){return S.shifts.flatMap(h=>{const sorted=h.segs.map(g=>({...g,wp:h.wp,sh:h.id})).sort((a,b)=>a.s-b.s),out=[];for(const g of sorted){const last=out.at(-1);if(last&&g.s<=last.e){last.e=Math.max(last.e,g.e);last.code=canonicalShift(wp(h.wp),h.text);last.aggregate=true}else out.push({...g})}return out}).sort((a,b)=>a.s-b.s)}
const wp=id=>S.wps.find(w=>w.id===id)||{name:'?',color:'#888'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bidi=(v,dir='auto')=>`<bdi dir="${dir}">${esc(v)}</bdi>`;
const codeHTML=v=>bidi(v,'ltr');
const dur=m=>{m=Math.max(0,Math.round(m));const h=Math.floor(m/60),n=m%60;return S.lang==='fa'?[h?`${h} ساعت`:'',n||!h?`${n} دقیقه`:''].filter(Boolean).join(' و '):[h?`${h} ${h===1?'hour':'hours'}`:'',n||!h?`${n} ${n===1?'minute':'minutes'}`:''].filter(Boolean).join(' ')};
const countdown=m=>{m=Math.max(0,Math.ceil(m));const days=Math.floor(m/1440);return days?`${days} ${S.lang==='fa'?'روز':days===1?'day':'days'}${m%1440?(S.lang==='fa'?' و ':' ')+dur(m%1440):''}`:dur(m)};
const placeColor=id=>S.themePlaces!==false?['var(--ac)','var(--ac-alt)','var(--ac-third)'][Math.max(0,S.wps.findIndex(w=>w.id===id))%3]:wp(id).color;
const hm=ms=>{const d=new Date(ms);return S.h24?String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'):d.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})};
const iso=d=>{d=new Date(d);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const loc=()=>S.lang==='fa'?(S.cal==='j'?'fa-IR-u-ca-persian':'fa-IR-u-ca-gregory'):(S.cal==='j'?'en-GB-u-ca-persian':'en-GB');
const dateText=value=>{const d=typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)?new Date(value+'T00:00'):new Date(value);const j=S.cal==='j'?jp(d):{d:d.getDate(),m:d.getMonth()+1,y:d.getFullYear()};return `${j.y}/${j.m}/${j.d}`};
const dateHTML=value=>codeHTML(dateText(value));
const dlabel=d=>new Date(d+'T00:00').toLocaleDateString(loc(),{weekday:'short'})+' · '+dateText(d);
const dayLabel=d=>`${new Date(d+'T00:00').toLocaleDateString(loc(),{weekday:'long'})} · ${dateHTML(d)}`;
const timeRange=(a,b)=>`${codeHTML(hm(a)+' – '+hm(b))}${iso(a)!==iso(b)?` <small class="mu">${T2('ends','پایان')} ${dateHTML(b)}</small>`:''}`;
const badge=(sh)=>(S.shifts.find(h=>h.id===sh)?.review?'<span class="bad g">Needs review</span>':'')+issues().filter(i=>i.a.sh===sh||i.b.sh===sh).map(i=>`<span class="bad ${i.t}">${i.t==='o'?'Overlap '+dur(i.min):'Gap '+dur(i.min)}</span>`).join(' ');
const segTxt=g=>`${codeHTML(g.code)} ${timeRange(g.s,g.e)}`;

/* ---------- UI ---------- */
const V={};
function go(t){closeDialog();if(t==='team'){tc.v='cover';tc.res=null;tc.filter='all';tc.notice=''}tab=t;render();window.scrollTo?.(0,0)}
function render(){const opened=$('#v').dataset.tab===tab?[...$('#v').querySelectorAll('details[open]')].map(d=>d.querySelector('summary')?.textContent):[];document.documentElement.dataset.ac=S.ac||'fox';document.documentElement.dataset.theme=S.theme==='auto'?'':S.theme;
  $('nav').innerHTML=NAV.slice(0,3).map(([k,i,l])=>`<button aria-current="${k===tab?'page':'false'}" class="${k===tab?'on':''}" onclick="go('${k}')"><i>${i}</i>${l}</button>`).join('');$('#v').innerHTML=V[tab]();$('#v').dataset.tab=tab;document.documentElement.lang=S.lang;document.documentElement.dir=S.lang==='fa'?'rtl':'ltr';hdr();tr($('nav'));tr($('#hd'));tr($('#v'));isolateMixed($('#v'));isolateMixed($('#hd'));$('#v').querySelectorAll('details').forEach(d=>{if(opened.includes(d.querySelector('summary')?.textContent))d.open=true})}
const autoDir=r=>r.querySelectorAll('input:not([dir]):not([type=file]):not([type=date]):not([type=time]):not([type=color]):not([type=checkbox]),textarea:not([dir])').forEach(i=>i.dir='auto');
const dlg=h=>{$('#dlg').innerHTML=`<button class="dialog-close" onclick="closeDialog()" aria-label="${T2('Close','بستن')}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 7 10 10M17 7 7 17"/></svg></button>`+h;autoDir($('#dlg'));tr($('#dlg'));isolateMixed($('#dlg'));$('#dlg').querySelectorAll('button').forEach(b=>{if(!b.classList.contains('dialog-close')&&b.getAttribute('onclick')?.trim()==='closeDialog()')b.classList.add('cancel-button')});if(!$('#dlg').open)$('#dlg').showModal()};function closeDialog(){const d=$('#dlg');if(d.open)d.close();}

const cLabel=g=>g.aggregate?(parse(wp(g.wp),g.code)||[]).map(c=>S.lang==='fa'?(FA[c.label]||c.label):c.label).join(' + '):(wp(g.wp).codes||[]).find(c=>c.code===g.code)?.label||g.code;
function hdr(){autoDir($('#v'));const L=NAV.find(n=>n[0]===tab)[2];$('#hd').innerHTML=`<div><b>${L}</b><span class="header-date mu">${dayLabel(iso(Date.now()))}</span></div>${['today','agenda','team'].includes(tab)?`<div class="header-controls"><button class="icon-button header-add ${tab==='team'||!S.shifts.length?'hidden':''}" onclick="addSchedule()" aria-label="${T2('Add schedule','افزودن برنامه')}">${T2('+ Schedule','+ برنامه')}</button><button class="icon-button" onclick="go('set')" aria-label="${T2('Settings','تنظیمات')}">⚙</button></div>`:`<button class="icon-button" onclick="go('${tab==='trip'?travel.returnTab:tab==='places'?'set':tab==='roster'?roster.returnTab:'today'}')">${T2('Back','برگشت')}</button>`}`;const f=document.querySelector('.fab');f.style.display='none';f.innerHTML=T2('+ Add schedule','+ افزودن برنامه')}
function addSchedule(){if(!S.wps.length)return go('setup');if(!S.shifts.length){resumeSetup();return}dlg(`<h3>${T2('Add schedule','افزودن برنامه')}</h3><button class="p" onclick="closeDialog();go('scan')">${T2('Scan roster photo','اسکن عکس برنامه')}</button><button class="p s" onclick="closeDialog();addShift()">${T2('Enter a shift manually','ثبت دستی شیفت')}</button><button class="text-button" onclick="closeDialog()">${T2('Cancel','لغو')}</button>`)}
const foxFill=(className='',progress)=>`<span class="loading-fox ${className}" style="${progress==null?'':'--loading-progress:'+progress+'%'}" aria-hidden="true"><span class="loading-fox-base fox-mark"></span><span class="loading-fox-fill fox-mark"></span></span>`;
const setupSteps=step=>`<ol class="setup-steps" aria-label="${T2('Setup progress','مراحل شروع')}">${[T2('Workplace','محل کار'),T2('Schedule','برنامه'),T2('Review','بررسی')].map((label,i)=>`<li class="${i+1<=step?'done':''}" ${i+1===step?'aria-current="step"':''}><b>${i+1<step?'✓':i+1}</b><span>${label}</span></li>`).join('')}</ol>`;
const isSettingUp=()=>S.onboarding?.stage==='scan'&&!S.shifts.some(h=>h.wp===S.onboarding.wp);
function resumeSetup(){const id=S.wps.find(w=>w.id===S.onboarding?.wp)?.id||S.wps[0]?.id;if(!id)return go('setup');S.onboarding={wp:id,stage:'scan'};sc.wp=id;sc.name=S.myname||'';save();go('scan')}
function finishSetup(id){if(S.onboarding?.wp===id)S.onboarding.stage='done'}
V.setup=()=>`${setupSteps(1)}<section class="c setup-card"><div class="setup-title"><span class="fox-mark"></span><h2>${T2('Let’s set up your schedule','از اینجا شروع کنیم')}</h2></div><p class="mu">${T2('Start with your workplace. Next, we’ll add your roster photo.','نام محل کارتان را بنویسید؛ بعد عکس برنامه را با هم بررسی می‌کنیم.')}</p><label>${T2('Workplace name','نام محل کار')}<input id="setup-workplace" maxlength="100" autocomplete="organization" placeholder="${T2('e.g. hospital or ward','مثلاً نام بیمارستان یا بخش')}"></label><label>${T2('Your name (optional)','نام شما (اختیاری)')}<input id="setup-name" maxlength="100" autocomplete="name" value="${esc(S.myname)}" placeholder="${T2('As written on the roster','همان نامی که در برنامه نوشته شده')}"></label><p class="setup-note">${T2('You can choose your name from the photo, and adjust shift symbols and hours anytime.','می‌توانید نامتان را از عکس انتخاب کنید. معنی علامت‌ها و ساعت شیفت‌ها هم قابل تغییرند.')}</p><button class="p" onclick="completeSetup()">${T2('Continue · Add schedule','ادامه · افزودن برنامه')}</button></section>`;
function completeSetup(){const name=$('#setup-workplace').value.trim();if(!name){$('#setup-workplace').focus();return alert(T2('What is your workplace called?','نام محل کارتان چیست؟'))}const w={id:'w'+Date.now(),name,color:'#ea8430',codes:decCodes(DEF.map(d=>d.join('|')).join('\n')),combos:[...DEFAULT_COMBOS]};S.wps.push(w);S.myname=$('#setup-name').value.trim();S.onboarding={wp:w.id,stage:'scan'};sc.wp=w.id;sc.name=S.myname;save();go('scan')}
V.today=()=>{if(!S.wps.length)return`<section class="c welcome-card"><span class="fox-mark welcome-fox" aria-hidden="true"></span><h2>${T2('Hello, welcome to FoxiOra','سلام، به FoxiOra خوش آمدید')}</h2><p class="mu">${T2('Your shifts, your free time, a little more clarity. Let’s start with your workplace and roster.','بیایید شیفت‌هایتان را کنار هم بچینیم و وقت آزاد را راحت‌تر پیدا کنیم. اول محل کار، بعد عکس برنامه.')}</p><button class="p" onclick="go('setup')">${T2('Let’s get started','شروع کنیم')}</button><small>${T2('Your schedule stays on this device.','برنامه‌تان روی همین دستگاه ذخیره می‌شود.')}</small></section>`;
 if(!S.shifts.length)return`${setupSteps(2)}<section class="c welcome-card"><h2>${T2('Your workplace is ready','محل کارتان آماده است')}</h2><p class="mu">${T2('Add a roster photo to see your shifts and free time together.','فقط عکس برنامه مانده؛ اضافه‌اش کنیم تا شیفت‌ها و وقت آزادتان یک‌جا دیده شوند.')}</p><button class="p" onclick="resumeSetup()">${T2('Add my schedule','افزودن برنامهٔ من')}</button><button class="text-button" onclick="addShift()">${T2('Enter shifts manually','ثبت دستی شیفت‌ها')}</button></section>`;
  const now=Date.now(),all=displaySegs(),current=all.filter(g=>g.s<=now&&now<g.e),cur=current[0],next=all.filter(g=>g.s>now),hero=cur||next[0],after=(cur?next:next.slice(1))[0];
  const hv=hero?`<section class="hero"><div class="row"><span class="pill">${cur?T2('ON SHIFT','در حال شیفت'):T2('NEXT SHIFT','شیفت بعدی')}</span><span class="hero-date">${dateHTML(hero.s)}</span></div>
    <div class="hero-main"><div><h2>${bidi(cLabel(hero))}</h2><div class="hero-place"><i style="background:${placeColor(hero.wp)}"></i>${bidi(wp(hero.wp).name)}</div></div><span class="hero-code">${codeHTML(hero.code)}</span></div>
    <div class="hero-time">${timeRange(hero.s,hero.e)}</div><div class="cd"><span>${cur?T2('Time remaining','تا پایان شیفت'):T2('Until your next shift','تا شیفت بعدی')}</span><strong>${countdown(((cur?cur.e:hero.s)-now)/6e4)}</strong></div>
    ${cur?`<div class="prog"><i style="width:${Math.min(100,Math.round((now-cur.s)/(cur.e-cur.s)*100))}%"></i></div>`:''}</section>`:`<div class="c empty-state"><b>${T2('Your schedule is clear','شیفت پیش‌رو ندارید')}</b><p class="mu">${T2('Add a shift or scan your next roster.','شیفت جدید اضافه کنید یا برنامه‌تان را اسکن کنید.')}</p></div>`;
  const today=new Date(),strip=Array.from({length:7},(_,i)=>{const d=new Date(today.getFullYear(),today.getMonth(),today.getDate()+i),ds=iso(d),hs=S.shifts.filter(h=>h.date===ds),hol=holidayInfo(d);return `<button class="dchip${i?'':' t'}${isWeekend(d)||hol.length?' holiday':''}" onclick="sel='${ds}';vm='month';cm=mfirst(new Date('${ds}T00:00'));go('agenda')"><span>${d.toLocaleDateString(loc(),{weekday:'short'})}</span><b>${S.cal==='j'?jp(d).d:d.getDate()}</b><em>${hs.length?hs.map(h=>codeHTML(h.text)).join(' '):'—'}</em></button>`}).join('');
  const weekEnd=new Date(today.getFullYear(),today.getMonth(),today.getDate()+7).getTime(),start=at(iso(now),'00:00'),week=all.filter(g=>g.s<weekEnd&&g.e>start),weekIssues=issues().filter(i=>i.b.s<weekEnd&&i.a.e>start),count=new Set(week.map(g=>g.sh)).size;
  return hv+`<div class="section-heading"><h1>${T2('THE NEXT 7 DAYS','هفت روز پیش‌رو')}</h1><button class="text-button" onclick="go('agenda')">${T2('Calendar','تقویم')}</button></div><div class="week-strip">${strip}</div>`+freePreview()+
    (new Set(current.map(g=>g.wp)).size>1?`<div class="c alert-card">${T2('More than one shift is active now. Check the overlapping times.','هم‌زمان بیش از یک شیفت فعال است. زمان‌های تداخل را بررسی کنید.')}</div>`:'')+
    weekIssues.slice(0,3).map(i=>`<div class="c alert-card"><b>${i.t==='o'?T2('Shift overlap','تداخل شیفت‌ها'):T2('Short break','فاصلهٔ کوتاه بین شیفت‌ها')} · ${dur(i.min)}</b><div class="mu">${bidi(wp(i.a.wp).name)} ${segTxt(i.a)}<br>${bidi(wp(i.b.wp).name)} ${segTxt(i.b)}</div></div>`).join('')};

const listV=()=>{const from=iso(Date.now()-DAY),l=[...S.shifts].filter(h=>h.date>=from).sort((a,b)=>a.date<b.date?-1:1);
  if(!l.length)return`<h1>AGENDA</h1><div class="c mu">No shifts yet. Tap + to add one.</div>`;
  let last='';return'<h1>AGENDA</h1>'+l.map(h=>{const head=h.date!==last?`<h1>${dlabel(h.date)}</h1>`:'';last=h.date;
   return head+`<div class="c bar row" style="--w:${placeColor(h.wp)}" role="button" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();editShift('${h.id}')}" onclick="editShift('${h.id}')"><div><b>${esc(h.text)}</b> · ${wp(h.wp).name}<div class="mu">${h.segs.map(segTxt).join(' + ')||h.label}</div></div><div>${badge(h.id)}<small class="edit-affordance">${T2('Edit','ویرایش')} ✎</small></div></div>`}).join('')};

V.places=()=>'<h1>WORKPLACES</h1>'+S.wps.map(w=>`<div class="c bar row" style="--w:${placeColor(w.id)}" onclick="editWp('${w.id}')"><div><b>${esc(w.name)}</b><div class="mu">${w.codes.map(c=>c.code).join(' ')}</div></div><span class="flip mu">›</span></div>`).join('')+`<button class="p" onclick="editWp()">+ Add workplace</button>`;
const settingSwitch=(key,label,hint='')=>`<label class="setting-row"><span><b>${label}</b>${hint?`<small>${hint}</small>`:''}</span><span class="switch-control"><input type="checkbox" role="switch" aria-label="${esc(label)}" ${S[key]?'checked':''} onchange="S.${key}=this.checked;save();render()"><span class="switch-track" aria-hidden="true"></span></span></label>`;
const settingsSelect=(key,label,items,value=S[key],change=`S.${key}=this.value`)=>`<label class="setting-field"><span>${label}</span><select onchange="${change};save();render()">${items.map(([v,l])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${l}</option>`).join('')}</select></label>`;
V.set=()=>{
 const group=(icon,title,body)=>`<details class="settings-group"><summary><span class="setting-icon" aria-hidden="true">${icon}</span><span>${title}</span></summary><div class="settings-body">${body}</div></details>`;
 const appearance=settingsSelect('lang',T2('Language','زبان'),[['fa','فارسی'],['en','English']])+settingsSelect('theme',T2('Display','حالت نمایش'),[['auto',T2('System','سیستم')],['light',T2('Light','روشن')],['dark',T2('Dark','تیره')]])+
 `<div class="setting-field"><span>${T2('Color theme','رنگ پوسته')}</span><div class="theme-choices" role="group" aria-label="${T2('Color theme','رنگ پوسته')}">${[['fox','Fox'],['ocean','Siren'],['forest','Forest'],['violet','Hedo']].map(([key,name])=>`<button class="theme-choice" data-palette="${key}" aria-pressed="${(S.ac||'fox')===key}" onclick="S.ac='${key}';save();render()"><i aria-hidden="true"></i><bdi dir="ltr">${name}</bdi>${(S.ac||'fox')===key?'<span aria-hidden="true">✓</span>':''}</button>`).join('')}</div></div>`+
 settingSwitch('h24',T2('24-hour clock','ساعت ۲۴ ساعته'),T2('Off: 12-hour clock with AM / PM','خاموش: ساعت ۱۲ ساعته با AM / PM'))+settingSwitch('themePlaces',T2('Match workplace colors to theme','هماهنگی رنگ محل‌های کار با پوسته'));
 const calendar=settingsSelect('cal',T2('Calendar','تقویم'),[['j',T2('Jalali','شمسی')],['g',T2('Gregorian','میلادی')]])+settingsSelect('fdow',T2('First day of week','شروع هفته'),[[6,T2('Saturday','شنبه')],[0,T2('Sunday','یکشنبه')],[1,T2('Monday','دوشنبه')]],S.fdow,'S.fdow=+this.value')+
 settingSwitch('holidays',T2('Public holidays','تعطیلات رسمی'))+settingsSelect('weekend',T2('Weekend','پایان هفته'),[['5',T2('Friday','جمعه')],['4,5',T2('Thursday & Friday','پنجشنبه و جمعه')],['6,0',T2('Saturday & Sunday','شنبه و یکشنبه')]],(S.weekend||[5]).join(','),"S.weekend=this.value.split(',').map(Number)")+`<p class="settings-note">${T2('Complete Iranian holiday dates are available for year 1405.','تعطیلات کامل ایران برای سال ۱۴۰۵ موجود است.')}</p>`;
 const memory=settingSwitch('learnOCR',T2('Remember scan corrections','یادآوری اصلاحات اسکن'),T2('Saved on this device and included in backups.','روی همین دستگاه و در نسخهٔ پشتیبان ذخیره می‌شود.'))+`<button class="p s" onclick="memoryDialog()">${T2('Manage saved corrections','مدیریت اصلاحات ذخیره‌شده')}</button>`;
 const alerts=settingsSelect('gap',T2('Minimum break between shifts','حداقل استراحت بین شیفت‌ها'),[60,120,240].map(x=>[x,dur(x)]),S.gap,'S.gap=+this.value')+settingSwitch('cross',T2('Check different workplaces','بررسی تداخل بین محل‌های کار'))+`<p class="settings-note">${T2('Combined duty at one workplace is not a conflict. Overlaps between different workplaces are checked.','شیفت ترکیبی در یک محل کار تداخل نیست؛ هم‌زمانی بین محل‌های کار متفاوت بررسی می‌شود.')}</p>`;
 const data=`<button class="p" onclick="exp()">${T2('Export backup','گرفتن نسخه پشتیبان')}</button><label class="p s restore-backup">${T2('Restore backup','بازیابی نسخه پشتیبان')}<input type="file" accept=".json" onchange="imp(this.files[0]);this.value=''" aria-label="${T2('Choose backup file','انتخاب فایل پشتیبان')}"></label><details class="danger-zone"><summary>${T2('Delete saved data','حذف اطلاعات ذخیره‌شده')}</summary><button class="p danger-button" onclick="if(confirm(T2('Delete all schedules and settings?','همهٔ برنامه‌ها و تنظیمات حذف شوند؟'))){S=DS();save();render()}">${T2('Clear all data','پاک کردن همهٔ اطلاعات')}</button></details>`;
 return `<button class="settings-workplaces" onclick="go('places')"><span class="setting-icon" aria-hidden="true">⌂</span><span><b>${T2('Workplaces & shift hours','محل‌های کار و ساعت شیفت‌ها')}</b><small>${S.wps.length} ${T2('saved workplaces','محل کار ثبت‌شده')}</small></span><span aria-hidden="true">›</span></button>`+
 group('◐',T2('Appearance & language','ظاهر و زبان'),appearance)+group('▦',T2('Calendar','تقویم'),calendar)+group('◎',T2('Scan memory','حافظهٔ اسکن'),memory)+group('!',T2('Shift alerts','هشدار شیفت‌ها'),alerts)+group('↥',T2('Backup & data','پشتیبان و اطلاعات'),data)+`<footer class="creator-card"><div class="creator-brand"><span class="fox-mark" aria-hidden="true"></span><bdi dir="ltr">FoxiOra</bdi><span class="version-badge">${VER}</span></div><a class="contact-link" href="https://t.me/i_2mt" target="_blank" rel="noopener noreferrer" aria-label="${T2('Contact Mohammad Mahdi Taghavi on Telegram','ارتباط با محمدمهدی تقوی از طریق تلگرام')}"><span><small>${T2('Designed & developed by','طراحی و توسعه')}</small><bdi dir="ltr">Mohammad Mahdi Taghavi</bdi></span><bdi dir="ltr">Telegram ↗</bdi></a></footer>`;
};

let wpDraft=[];
function groupedCodes(w){const off=w.codes.filter(c=>c.type==='off'),rest=w.codes.filter(c=>c.type!=='off').map(c=>({...c,aliases:[...(c.aliases||[])]}));if(off.length){const c=off.find(c=>c.code==='-')||off[0];rest.push({...c,code:offCode(w),aliases:[...new Set(off.flatMap(x=>[x.code,...(x.aliases||[])]).concat(['OFF','*','-']))].filter(x=>x!==offCode(w)&&!rest.some(c=>c.code===x||(c.aliases||[]).includes(x)))})}return rest}
function codeEditorRows(){return wpDraft.map((c,i)=>`<details class="code-editor" data-index="${i}"><summary><bdi dir="ltr">${esc(c.code||'?')}</bdi><span>${esc(c.label)}</span><small>${c.type==='off'?T2('Off','تعطیل'):c.type==='leave'?T2('Leave','مرخصی'):c.start+' – '+c.end}</small></summary><div class="code-fields"><label>${T2('Symbol in your roster','علامت در برنامه')}<input class="code-value" dir="auto" value="${esc(c.code)}" autocapitalize="off"></label><label>${T2('Meaning','معنی')}<input class="code-label" value="${esc(c.label)}"></label><label>${T2('Kind','نوع')}<select class="code-type" onchange="this.closest('.code-editor').querySelector('.code-times').hidden=this.value!=='work'">${['work','off','leave'].map(t=>`<option value="${t}" ${c.type===t?'selected':''}>${t==='work'?T2('Work','شیفت'):t==='off'?T2('Off','تعطیل'):T2('Leave','مرخصی')}</option>`).join('')}</select></label><label>${T2('Other symbols with this meaning','علامت‌های هم‌معنی')}<input class="code-alias" dir="auto" placeholder="${T2('Separate with commas','با ویرگول جدا کنید')}" value="${esc((c.aliases||[]).join(', '))}"></label><div class="code-times" ${c.type!=='work'?'hidden':''}><label>${T2('Start','شروع')}<input class="code-start" type="time" value="${c.start||'07:30'}"></label><label>${T2('End','پایان')}<input class="code-end" type="time" value="${c.end==='24:00'?'00:00':c.end||'14:30'}"></label></div></div><button class="text-button danger-text" onclick="removeCode(${i})">${T2('Remove symbol','حذف علامت')}</button></details>`).join('')}
function collectCodes(){return [...$('#code-rows').querySelectorAll('.code-editor')].map(r=>({code:nrm(r.querySelector('.code-value').value.trim()),label:r.querySelector('.code-label').value.trim(),type:r.querySelector('.code-type').value,start:r.querySelector('.code-start').value,end:r.querySelector('.code-end').value,aliases:nrm(r.querySelector('.code-alias').value).split(/[,،]/).map(x=>x.trim()).filter(Boolean)}))}
function appendCode(){wpDraft=collectCodes();wpDraft.push({code:'',label:'',type:'work',start:'07:30',end:'14:30',aliases:[]});$('#code-rows').innerHTML=codeEditorRows();$('#code-rows').lastElementChild.open=true;$('#code-rows').lastElementChild.querySelector('input').focus()}
function removeCode(i){wpDraft=collectCodes();wpDraft.splice(i,1);$('#code-rows').innerHTML=codeEditorRows()}
function editWp(id,showCodes=false){const w=S.wps.find(x=>x.id===id)||{name:'',color:'#bd541b',codes:decCodes(DEF.map(d=>d.join('|')).join('\n'))};wpDraft=groupedCodes(w);
 dlg(`<h3>${id?T2('Edit workplace','ویرایش محل کار'):T2('New workplace','محل کار جدید')}</h3><label>${T2('Name','نام')}<input id="wn" value="${esc(w.name)}" placeholder="${T2('Hospital / ward','بیمارستان / بخش')}"></label><details class="symbol-setup" ${showCodes||!id?'open':''}><summary>${T2('Teach roster symbols & hours','تعریف علامت‌ها و ساعت شیفت‌ها')}</summary><p class="mu">${T2('Tap a symbol to set its meaning and hours. Off aliases (−, OFF, *) share one meaning. Changes apply to new entries; saved shift times stay unchanged.','هر علامت را باز کنید و معنی و ساعتش را مشخص کنید. علامت‌های تعطیل مثل − و OFF هم‌معنی‌اند. تغییر ساعت‌ها برای ثبت‌های جدید است.')}</p><div id="code-rows">${codeEditorRows()}</div><button class="p s" onclick="appendCode()">${T2('+ Add symbol','+ افزودن علامت')}</button><label class="setup-combos">${T2('Allowed combined shifts','شیفت‌های ترکیبی مجاز')}<input id="wcm" dir="ltr" value="${esc((w.combos??DEFAULT_COMBOS).join(', '))}" placeholder="DE, En"></label><small class="mu">${T2('For example DE: morning + evening, including their handover overlap.','مثلاً DE: صبح و عصر، با زمان مشترک تحویل شیفت.')}</small></details><details><summary>${T2('Other workplace options','گزینه‌های دیگر محل کار')}</summary><label class="setting-row"><span><b>${T2('Include in free time and trips','در محاسبهٔ وقت آزاد و سفر لحاظ شود')}</b></span><span class="switch-control"><input id="wa" type="checkbox" role="switch" ${w.active!==false?'checked':''}><span class="switch-track" aria-hidden="true"></span></span></label><label class="setting-row"><span><b>${T2('Day off after a night shift','یک روز تعطیل پس از شیفت شب')}</b><small>${T2('Applies to cover and exchange suggestions.','در پیشنهاد جایگزین و تعویض بررسی می‌شود.')}</small></span><span class="switch-control"><input id="wno" type="checkbox" role="switch" ${w.nightOff!==false?'checked':''}><span class="switch-track" aria-hidden="true"></span></span></label><label>${T2('Workplace color','رنگ محل کار')}<input id="wc" type="color" value="${esc(w.color||'#bd541b')}"></label></details><div class="dialog-actions"><button class="p" onclick="saveWp('${id||''}')">Save</button><button class="p s" onclick="closeDialog()">${T2('Cancel','لغو')}</button></div>${id?`<details class="danger-zone"><summary>${T2('Remove workplace','حذف محل کار')}</summary><button class="p danger-button" onclick="delWp('${id}')">Delete</button></details>`:''}`)}
function saveWp(id){const n=$('#wn').value.trim();if(!n)return alert(T2('Enter a workplace name.','نام محل کار را وارد کنید.'));const codes=collectCodes();
 const tokens=new Map();for(const c of codes){if(!c.code||!c.label||/[\s,،|]/.test(c.code)||(c.type==='work'&&(!/^\d{2}:\d{2}$/.test(c.start)||!/^\d{2}:\d{2}$/.test(c.end))))return alert(T2('Check symbol names, meanings and hours.','علامت‌ها، معنی و ساعت‌ها را بررسی کنید.'));for(const token of [c.code,...c.aliases]){if(tokens.has(token)&&tokens.get(token)!==c.code)return alert(T2('A symbol has more than one meaning: ','این علامت چند معنی دارد: ')+token);tokens.set(token,c.code)}}
 if(!codes.length)return alert(T2('Add at least one symbol.','حداقل یک علامت تعریف کنید.'));const o={name:n,color:$('#wc').value,active:$('#wa').checked,nightOff:$('#wno').checked,codes};o.combos=nrm($('#wcm').value).split(/[,\s،]+/).filter(Boolean);
 if(o.combos.some(x=>{const c=parse(o,x);return !c||c.length<2||c.some(y=>y.type!=='work')}))return alert(T2('Combined shifts must contain two or more working symbols.','شیفت ترکیبی باید شامل حداقل دو علامت کاری باشد.'));
 if(id)Object.assign(S.wps.find(w=>w.id===id),o);else S.wps.push({id:'w'+Date.now(),...o});normalizeSavedOff();save();closeDialog();render()}
function normalizeSavedOff(){for(const w of S.wps){for(const h of S.shifts.filter(x=>x.wp===w.id)){const c=parse(w,h.text);if(!h.segs.length&&c?.every(x=>x.type==='off'))h.text=offCode(w)}for(const m of mates(w.id))for(const [d,t] of Object.entries(m.cells)){const c=parse(w,t);if(c?.every(x=>x.type==='off'))m.cells[d]=offCode(w)}}}
function delWp(id){if(!confirm('Delete workplace and its shifts?'))return;S.wps=S.wps.filter(w=>w.id!==id);S.shifts=S.shifts.filter(h=>h.wp!==id);save();closeDialog();render()}

function presetCodes(w){return [...w.codes.filter(c=>c.type!=='off').map(c=>({code:c.code,label:c.label})),...((w.combos??DEFAULT_COMBOS).filter(t=>parse(w,t)).map(code=>({code,label:T2('Combined','ترکیبی')}))),...(offCode(w)?[{code:offCode(w),label:T2('Off','تعطیل')}]:[])]}
function chips(){const w=S.wps.find(x=>x.id===$('#fw').value);if(!w)return;$('#ch').innerHTML=presetCodes(w).map(c=>`<button type="button" class="shift-key" aria-pressed="${canonicalShift(w,$('#fc').value)===c.code}" onclick="chooseShiftKey(${esc(JSON.stringify(c.code))})"><bdi dir="ltr">${esc(c.code)}</bdi><small>${esc(c.label)}</small></button>`).join('');tr($('#ch'));isolateMixed($('#ch'))}
function chooseShiftKey(code){$('#fc').value=code;chips()}
let editingShift='';
function addShift(date=iso(Date.now())){editingShift='';if(!S.wps.length)return go('setup');
 dlg(`<h3 id="shift-heading">${T2('Add shift','ثبت شیفت')}</h3><div class="shift-fields"><label>${T2('Workplace','محل کار')}<select id="fw" onchange="$('#fc').value='';chips()">${S.wps.map(w=>`<option value="${w.id}">${esc(w.name)}</option>`).join('')}</select></label><label>${T2('Date','تاریخ')}${dField('fd',date)}</label></div><p class="mu">${T2('Choose the new shift.','شیفت جدید را انتخاب کنید.')}</p><div id="ch" class="shift-keys"></div><label class="custom-shift">${T2('Or enter a custom combination','یا ترکیب دلخواه وارد کنید')}<input id="fc" dir="ltr" autocapitalize="off" oninput="chips()" placeholder="D / E / DE / −"></label><div class="dialog-actions"><button class="p" onclick="saveShift()">Save</button><button class="p s" onclick="closeDialog()">${T2('Cancel','لغو')}</button></div>`);chips()}
function editShift(id){const h=S.shifts.find(x=>x.id===id);if(!h)return;addShift(h.date);editingShift=id;$('#shift-heading').textContent=T2('Edit / change shift','ویرایش / تغییر شیفت');$('#fw').value=h.wp;$('#fc').value=canonicalShift(wp(h.wp),h.text);chips();$('#dlg').insertAdjacentHTML('beforeend',`<button class="text-button danger-text" onclick="deleteEditedShift('${id}')">${T2('Delete shift','حذف شیفت')}</button>`)}
function deleteEditedShift(id){if(confirm(T2('Delete this shift?','این شیفت حذف شود؟'))){S.shifts=S.shifts.filter(h=>h.id!==id);save();closeDialog();render()}}
function saveShift(){const w=S.wps.find(x=>x.id===$('#fw').value),d=dGet('fd'),t=canonicalShift(w,nrm($('#fc').value.trim())),cs=parse(w,t);
  if(!d||!cs)return alert(T2('Check the date and shift symbol.','تاریخ و علامت شیفت را بررسی کنید.'));
  S.shifts=S.shifts.filter(h=>h.id!==editingShift&&!(h.wp===w.id&&h.date===d)); // re-entering a day replaces it (no duplicates)
  S.shifts.push({id:'s'+Date.now(),wp:w.id,date:d,text:t,label:cs.map(c=>c.label).join(' + '),segs:makeSegs(d,cs)});finishSetup(w.id);save();closeDialog();render()}
function delShift(id){if(confirm('Delete this shift?')){S.shifts=S.shifts.filter(h=>h.id!==id);save();render()}}
function exp(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(S)],{type:'application/json'}));a.download='FoxiOra-backup.json';a.click()}
async function imp(f){if(f){S={...DS(),...JSON.parse(await f.text())};normalizeSavedOff();save();render()}}


