const monthV=()=>{const first=mfirst(cm),J=S.cal==='j',key=d=>J?jp(d).m:d.getMonth(),days=[];
  for(let d=first;key(d)===key(first);d=new Date(d.getFullYear(),d.getMonth(),d.getDate()+1))days.push(d);
  const off=(first.getDay()-S.fdow+7)%7,bad=new Set(issues().flatMap(i=>[iso(i.a.s),iso(i.b.s)])),td=iso(Date.now());
  const wd=Array.from({length:7},(_,i)=>{const d=new Date(2024,0,7+(i+S.fdow)%7);return `<div class="weekday${isWeekend(d)?' holiday':''}">${d.toLocaleDateString(loc(),{weekday:'short'})}</div>`}).join('');
  let cells='<div></div>'.repeat(off);
  for(const d of days){const ds=iso(d),hs=S.shifts.filter(h=>h.date===ds),hol=holidayInfo(d),events=S.events.filter(e=>e.s<at(ds,'00:00')+DAY&&e.e>at(ds,'00:00'));cells+=`<button class="cell${ds===sel?' sel':''}${ds===td?' t':''}${isWeekend(d)||hol.length?' holiday':''}" onclick="pick('${ds}')" aria-current="${ds===td?'date':'false'}" aria-pressed="${ds===sel}" aria-label="${esc(dlabel(ds)+' '+hol.join('، '))}"><b class="day-number">${J?jp(d).d:d.getDate()}</b>${hol.length?'<span class="holiday-dot" aria-hidden="true"></span>':''}${hs.slice(0,2).map(h=>shiftMark(wp(h.wp),h.text)).join('')}${hs.length>2?`<small>+${hs.length-2}</small>`:''}${events.length?'<span class="event-dot">•</span>':''}${bad.has(ds)?'<u></u>':''}</button>`}
  return `<section class="calendar-panel"><div class="row month-heading"><button class="flip" onclick="mv(-1)" aria-label="${T2('Previous month','ماه قبل')}">‹</button><b>${first.toLocaleDateString(loc(),{month:'long',year:'numeric'})}</b><button class="text-button calendar-today" onclick="sel=iso(Date.now());cm=mfirst(new Date());render()">${T2('Go to today','رفتن به امروز')}</button><button class="flip" onclick="mv(1)" aria-label="${T2('Next month','ماه بعد')}">›</button></div><div class="grid">${wd}${cells}</div><div class="calendar-legend"><span class="today-legend"><i></i>${T2('Today','امروز')}</span><span class="holiday">● ${T2('Weekend / holiday','پایان هفته / تعطیل')}</span><span>• ${T2('Personal event','برنامهٔ شخصی')}</span></div>${S.holidays!==false&&jp(first).y!==1405?`<p class="mu">${T2('Lunar holidays have not been loaded for this year.','تعطیلات قمری این سال هنوز بارگذاری نشده است.')}</p>`:''}</section>`+dayV()};
// Week view: one 24-hour bar per day, shifts as colored blocks (overlaps outlined red, personal events grey).
const shiftSel=n=>{const d=new Date(sel+'T00:00');sel=iso(new Date(d.getFullYear(),d.getMonth(),d.getDate()+n));render()};
const weekV=()=>{const d0=new Date(sel+'T00:00'),st=new Date(d0.getFullYear(),d0.getMonth(),d0.getDate()-((d0.getDay()-S.fdow+7)%7)),en=new Date(st.getFullYear(),st.getMonth(),st.getDate()+6),sg=segs(),td=iso(Date.now()),
  bad=new Set(issues().filter(i=>i.t==='o').flatMap(i=>[i.a.sh+':'+i.a.s,i.b.sh+':'+i.b.s])),sh=d=>d.toLocaleDateString(loc(),{day:'numeric',month:'short'});
  const rows=[...Array(7)].map((_,k)=>{const d=new Date(st.getFullYear(),st.getMonth(),st.getDate()+k),a=d.getTime(),b=a+DAY,ds=iso(d);
    const blk=[...sg.filter(g=>g.s<b&&g.e>a).map(g=>({s:g.s,e:g.e,t:g.code,c:placeColor(g.wp),bad:bad.has(g.sh+':'+g.s)})),...S.events.filter(e=>e.s<b&&e.e>a).map(e=>({s:e.s,e:e.e,t:e.title,c:'#8b95a1'}))].map(x=>{const l=Math.max(x.s,a),r=Math.min(x.e,b),w=(r-l)/DAY*100;return `<i class="blk${x.bad?' bad':''}" style="left:${(l-a)/DAY*100}%;width:${w}%;background:${x.c}">${w>9?x.t:''}</i>`}).join('');
    const off=S.shifts.filter(h=>h.date===ds&&!h.segs.length).map(h=>h.text).join(' ');
    return `<div class="wk${isWeekend(d)||holidayInfo(d).length?' holiday':''}${ds===td?' t':''}${ds===sel?' s':''}" onclick="sel='${ds}';render()"><div class="wd"><b>${d.toLocaleDateString(loc(),{day:'numeric'})}</b><span class="mu">${d.toLocaleDateString(loc(),{weekday:'short'})}</span></div><div class="trk">${blk}${off?`<span class="off">${off}</span>`:''}</div></div>`}).join('');
  return `<div class="row"><button class="flip" onclick="shiftSel(-7)">‹</button><b>${sh(st)} – ${sh(en)}</b><button class="flip" onclick="shiftSel(7)">›</button></div><div class="wk hd"><div></div><div class="trk ax"><span style="left:0">00</span><span style="left:25%">06</span><span style="left:50%">12</span><span style="left:75%">18</span></div></div>${rows}`+dayV()};
const dayV=()=>{const hs=S.shifts.filter(h=>h.date===sel),ev=S.events.filter(e=>e.s<at(sel,'00:00')+DAY&&e.e>at(sel,'00:00'));
  return `<h1>${dayLabel(sel)}</h1>`+holidayInfo(new Date(sel+'T00:00')).map(t=>`<div class="holiday-note">${esc(t)}</div>`).join('')+hs.map(h=>`<div class="c bar row" style="--w:${placeColor(h.wp)}" role="button" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();editShift('${h.id}')}" onclick="editShift('${h.id}')"><div><b>${esc(h.text)}</b> · ${wp(h.wp).name}<div class="mu">${h.segs.map(segTxt).join(' + ')||h.label}</div></div><div>${badge(h.id)}<small class="edit-affordance">${T2('Edit','ویرایش')} ✎</small></div></div>`).join('')
   +ev.map(e=>`<div class="c" onclick="delEvent('${e.id}')"><b>${esc(e.title)}</b><div class="mu">${timeRange(e.s,e.e)}</div></div>`).join('')+`<div class="day-actions"><button class="p s" onclick="editDayShift()">${T2('Add / change shift','ثبت / تغییر شیفت')}</button><button class="p s" onclick="addEvent()">${T2('+ Event','+ برنامهٔ شخصی')}</button></div>`};
// Continuous gaps across dates. Unknown roster days are blocked for trip planning.
function freeWindows(minMinutes=0,{start=Math.ceil(Date.now()/6e4)*6e4,end,excludeShift=''}={}){
  const known=S.rosterDays||{},dated=S.shifts.map(h=>({wp:h.wp,date:h.date}));
  for(const key of Object.keys(known)){const cut=key.lastIndexOf('|');dated.push({wp:key.slice(0,cut),date:key.slice(cut+1)})}
  const active=S.wps.filter(w=>w.active!==false&&dated.some(d=>d.wp===w.id));
  if(!active.length)return {slots:[],start,end:start,unknownDays:0};
  const last=active.map(w=>dated.filter(d=>d.wp===w.id).map(d=>at(d.date,'00:00')+DAY).sort((a,b)=>b-a)[0]);
  end=Math.min(end||start+60*DAY,...last);if(end<=start)return {slots:[],start,end,unknownDays:0};
  const busy=[...segs().filter(g=>g.sh!==excludeShift),...S.events],unknown=new Set();
  for(let d=at(iso(start),'00:00');d<end;d+=DAY){const date=iso(d);if(active.some(w=>!S.shifts.some(h=>h.wp===w.id&&h.date===date&&!h.review)&&known[w.id+'|'+date]!==true)){busy.push({s:d,e:d+DAY});unknown.add(date)}}
  busy.sort((a,b)=>a.s-b.s);const slots=[];let p=start;
  for(const g of busy){if(g.e<=p||g.s>=end)continue;const stop=Math.min(end,g.s);if(stop>p&&(stop-p)/6e4>=minMinutes)slots.push([p,stop]);p=Math.max(p,g.e)}
  if(end>p&&(end-p)/6e4>=minMinutes)slots.push([p,end]);
  return {slots,start,end,unknownDays:unknown.size};
}
function free(min){return freeWindows(min).slots}
const gapDuration=(a,b)=>countdown(Math.floor((b-a)/6e4));
const windowRange=(a,b)=>`<div class="window-endpoint"><span>${T2('From','از')}</span><b>${dateHTML(a)}</b>${codeHTML(hm(a))}</div><div class="window-endpoint"><span>${T2('Until','تا')}</span><b>${dateHTML(b)}</b>${codeHTML(hm(b))}</div>`;
