const freeV=()=>{const data=freeWindows(S.fh*60),slots=data.slots;
 return `<section class="free-panel"><div class="row"><label for="free-minimum" class="mu">Free for at least</label><select id="free-minimum" onchange="S.fh=+this.value;save();render()">${[1,2,3,4,24,48].map(h=>`<option value="${h}" ${S.fh===h?'selected':''}>${countdown(h*60)}</option>`).join('')}</select></div><p class="mu free-help">${T2('Continuous time, including nights, up to the end of your saved roster. Days without a roster are unknown.','بازه‌های پیوسته، شامل شب‌ها، تا پایان برنامهٔ ثبت‌شده. روزهای بدون برنامه نامشخص‌اند.')}</p>`+
 (slots.length?slots.map(([a,b],i)=>`${i===3?`<details class="more-free"><summary>${T2('More free periods','بازه‌های دیگر')}</summary>`:''}<div class="free-window"><div class="compact-window">${windowRange(a,b)}</div><span class="duration-pill">${gapDuration(a,b)}</span></div>`).join('')+(slots.length>3?'</details>':''):`<p class="mu">${T2('No known free period matches this duration.','بازهٔ آزاد مشخصی با این مدت پیدا نشد.')}</p>`)+`<button class="p s" onclick="openTrip()">${T2('Plan a trip or longer break','برنامه‌ریزی سفر یا استراحت طولانی')}</button></section>`};
