function openTrip(){travel.returnTab=['today','agenda','team'].includes(tab)?tab:'today';travel.from=travel.from||iso(Date.now());travel.searched=false;go('trip')}
function changeTrip(){const from=dGet('trip-from');if(from)travel.from=from;travel.days=Math.max(1,Math.min(14,+$('#trip-days').value||2));travel.searched=true;render()}
function tripCalc({days=travel.days,from=travel.from||iso(Date.now())}={}){
 const start=Math.max(at(from,'00:00'),Math.ceil(Date.now()/6e4)*6e4),base=freeWindows(0,{start}),needed=days*DAY,ready=base.slots.filter(([a,b])=>b-a>=needed),swaps=[];
 for(const h of S.shifts){if(h.review||!h.segs.length||Math.min(...h.segs.map(g=>g.s))<start||!h.segs.some(g=>g.e>start&&g.s<base.end))continue;
   const altered=freeWindows(0,{start,end:base.end,excludeShift:h.id});
   const gap=altered.slots.filter(([a,b])=>b-a>=needed&&h.segs.some(g=>g.s<b&&g.e>a)).sort((a,b)=>(b[1]-b[0])-(a[1]-a[0]))[0];if(!gap)continue;
   const previous=Math.max(0,...base.slots.map(([a,b])=>Math.max(0,Math.min(b,gap[1])-Math.max(a,gap[0])))),gain=gap[1]-gap[0]-previous;
   if(gain<12*3600000)continue;const w=wp(h.wp),cover=coverCalc(w,[h.id]).rows[0];swaps.push({h,gap,gain,previous,people:[...(cover?.free||[]),...(cover?.ext||[])].filter(x=>(!x.f.p||x.f.p.g>=S.gap)&&(!x.f.n||x.f.n.g>=S.gap)),unknown:cover?.unk.length||0})
 }
 swaps.sort((a,b)=>Number(b.people.length>0)-Number(a.people.length>0)||(b.gap[1]-b.gap[0])-(a.gap[1]-a.gap[0]));
 return {...base,ready,swaps:swaps.slice(0,3),needed};
}
function openTripSwap(id){const h=S.shifts.find(x=>x.id===id);if(!h)return;tc.wp=h.wp;tc.dates=[id];go('team');coverGo()}
