function coverRequest(hid,mid){const h=S.shifts.find(x=>x.id===hid),m=S.mates.find(x=>x.id===mid),row=h&&coverCalc(wp(h.wp),[hid]).rows[0],x=row&&[...row.free,...row.ext].find(x=>x.m.id===mid);if(!h||!m||!x)return alert(T2('Find options again; the roster changed.','برنامه تغییر کرده؛ پیشنهادها را دوباره پیدا کنید.'));const text=T2(`Hi ${m.name}, could you take my ${h.text} shift on ${dateText(h.date)}?${x.combo?` Your ${x.current} would become ${x.combo}.`:''} Let me know if it works for you.`,`سلام ${m.name}، می‌توانی شیفت ${h.text} من در ${dateText(h.date)} را بگیری؟${x.combo?` شیفت ${x.current} تو به ${x.combo} تبدیل می‌شود.`:''} اگر برایت مناسب است، هماهنگ کنیم.`);dlg(`<h3>${T2('Request draft','پیش‌نویس درخواست')}</h3><p class="mu">${T2('Copy and send it yourself when you’re ready.','اگر مناسب است، متن را کپی کنید و خودتان بفرستید.')}</p><textarea id="request-draft" rows="5" dir="auto">${esc(text)}</textarea><div class="dialog-actions"><button class="p" onclick="copyCoverRequest()">${T2('Copy text','کپی متن')}</button><button class="p s" onclick="closeDialog()">${T2('Close','بستن')}</button></div><p id="request-status" role="status" class="mu"></p>`)}
