function renMate(id){const m=S.mates.find(x=>x.id===id);if(!m)return;
  dlg(`<h3>${T2('Correct colleague name','اصلاح نام همکار')}</h3>${m.img?`<img class="name-preview" src="${m.img}" alt="${T2('Name from the roster','نام در تصویر برنامه')}">`:''}<label for="mate-name" class="mu">${T2('Correct name','نام صحیح')}</label><input id="mate-name" dir="auto" value="${esc(m.name)}"><p class="mu">${T2('This correction will help recognize the same name in future scans on this device.','این اصلاح به تشخیص همین نام در اسکن‌های بعدی روی این دستگاه کمک می‌کند.')}</p><button class="p" onclick="saveMateName('${id}')">Save</button><button class="p s" style="margin-top:8px" onclick="closeDialog()">${T2('Cancel','لغو')}</button>`)}
function saveMateName(id){const m=S.mates.find(x=>x.id===id),name=$('#mate-name').value.trim();if(!m||!name)return;rememberExample('names',m.wp,m.nameFeature,m.rawName||m.name,name);m.name=name;save();closeDialog();render()}
const delMate=id=>{if(confirm(T2('Remove this colleague?','این همکار حذف بشه؟'))){S.mates=S.mates.filter(m=>m.id!==id);save();render()}};
const noMates=()=>`<div class="c"><b>${T2('No colleagues yet','هنوز همکاری ثبت نشده')}</b><p class="mu">${T2('Scan the roster and choose “Import and read colleagues”. Their shifts stay on this phone.','برنامه رو اسکن کن و «ثبت و خواندن برنامهٔ همکاران» رو بزن. شیفت همکارها فقط روی همین گوشی می‌مونه.')}</p>${sc.pages&&sc.pages.length?`<button class="p" onclick="readAll()">${T2('Read colleagues from the last scan','خوندن همکارها از آخرین اسکن')}</button>`:`<button class="p s" onclick="go('scan')">${T2('Scan colleague roster','اسکن برنامهٔ همکاران')}</button>`}</div>`;
const mateList=(w,ms)=>`<p class="mu">${T2('Tap a name to correct it and remember it for future scans.','برای اصلاح و یادآوری در اسکن‌های بعدی، روی نام همکار بزنید.')}</p>`+ms.map(m=>`<div class="pk"><span style="display:flex;gap:8px;align-items:center">${m.img?`<img class="nm" src="${m.img}">`:''}<button class="name-edit" onclick="renMate('${m.id}')">${bidi(m.name||'?')} <span aria-hidden="true">✎</span></button></span><span class="mu">${Object.values(m.cells).filter(t=>isWork(w,t)).length} ${T2('shifts','شیفت')} <button class="x" onclick="delMate('${m.id}')">✕</button></span></div>`).join('')+(sc.pages&&sc.pages.length?`<button class="p s" style="margin-top:6px" onclick="readAll()">${T2('Read colleagues from the last scan','خوندن همکارها از آخرین اسکن')}</button>`:'');
const coverCard=(r,x)=>`<article class="swap-option"><div class="option-heading"><b>${bidi(x.m.name)}</b><span class="option-kind">${x.combo?T2('Combined duty','شیفت ترکیبی'):T2('Covers you','جای شما می‌آید')}</span></div><p>${T2('You are off; they take your shift.','شما تعطیل می‌شوید؛ همکارتان شیفت را می‌گیرد.')}</p><div class="option-transfer"><span>${T2('Their shift','شیفت همکار')}</span><b>${codeHTML(x.current)} <span aria-hidden="true">→</span> ${codeHTML(x.combo||r.h.text)}</b></div>${x.nightChecked?`<small class="exchange-check">✓ ${T2('Their post-night day off is clear.','روز تعطیل پس از شب برای همکارتان مشخص است.')}</small>`:''}<details class="option-facts"><summary>${T2('Nearby shifts & breaks','شیفت‌های نزدیک و استراحت')}</summary><p>${factTxt(x.f)||T2('No neighboring work shift recorded.','شیفت کاری مجاوری ثبت نشده است.')}</p><small>${T2('Based on saved data; check any missing dates.','بر اساس برنامهٔ ثبت‌شده؛ روزهای ثبت‌نشده را بررسی کنید.')}</small></details><button class="text-button request-button" onclick="coverRequest('${r.h.id}','${x.m.id}')">${T2('Prepare a request','آماده کردن درخواست')}</button></article>`;
const exchangeCard=(r,x)=>`<article class="swap-option exchange-option"><div class="option-heading"><b>${bidi(x.m.name)}</b><span class="option-kind">${T2('Exchange','دوطرفه')}</span></div><div class="exchange-summary"><p><span>${T2('They take','همکارتان می‌گیرد')}</span><b>${codeHTML(x.give)} · ${dateHTML(r.h.date)}</b></p><p><span>${T2('You take','شما می‌گیرید')}</span><b>${codeHTML(x.take)} · ${dateHTML(x.date)}</b></p></div>${x.nightChecked?`<small class="exchange-check">✓ ${T2('Post-night days off checked for both','تعطیل بعد از شب، برای هر دو نفر بررسی شد')}</small>`:''}<button class="p s" onclick="exchangePreview('${r.h.id}','${x.m.id}','${x.date}')">${T2('Preview exchange','دیدن تعویض')}</button></article>`;
function coverResults(R){const totalCover=R.rows.reduce((n,r)=>n+r.free.length+r.ext.length,0),totalSwap=R.rows.reduce((n,r)=>n+r.swap.length,0),filter=tc.filter||'all';
 const filters=`<div class="swap-filters" role="group" aria-label="${T2('Option type','نوع پیشنهاد')}">${[['all',T2('All','همه'),totalCover+totalSwap],['swap',T2('Exchange','دوطرفه'),totalSwap],['cover',T2('Cover','جایگزین'),totalCover]].map(([key,label,count])=>`<button aria-pressed="${filter===key}" onclick="tc.filter='${key}';render()">${label}<small>${count}</small></button>`).join('')}</div>`;
 const section=(title,subtitle,arr,fn)=>arr.length?`<section class="option-section"><h2>${title}<span>${arr.length}</span></h2><p class="option-subtitle">${subtitle}</p>${arr.slice(0,3).map(fn).join('')}${arr.length>3?`<details class="more-options"><summary>${T2('More options','گزینه‌های بیشتر')} · ${arr.length-3}</summary>${arr.slice(3).map(fn).join('')}</details>`:''}</section>`:'';
 return filters+(R.rows.length>1?`<p class="multi-shift-note">${T2('Each exchange below is a separate choice. Check again after saving one.','هر تعویض زیر یک انتخاب جداگانه است؛ پس از ثبت یکی، دوباره بررسی کنید.')}</p>${R.all.length?`<details class="common-cover"><summary>${T2('Can cover all selected shifts','می‌توانند همهٔ شیفت‌های انتخاب‌شده را بگیرند')}</summary><p>${R.all.map(m=>bidi(m.name)).join('، ')}</p></details>`:''}`:'')+R.rows.map(r=>{const cover=[...r.free,...r.ext],shownCover=filter!=='swap',shownSwap=filter!=='cover';const pending=[...r.unk,...r.pending],unique=[...new Map(pending.map(x=>[x.m.id+'|'+x.reason+'|'+x.date,x])).values()];return`<section class="shift-options"><div class="selected-shift-heading"><b>${codeHTML(r.h.text)} · ${dateHTML(r.h.date)}</b><span>${T2('Your shift','شیفت شما')}</span></div>`+

 (shownSwap?section(T2('You exchange two shifts','دو شیفت را جابه‌جا می‌کنید'),T2('They take yours; you take one of theirs.','شیفت شما برای همکارتان؛ یک شیفت او برای شما.'),r.swap,x=>exchangeCard(r,x)):'')+
 (shownCover?section(T2('Someone takes your shift','کسی جای شما می‌آید'),T2('No shift to take in return.','بدون شیفت برگشتی برای شما.'),cover,x=>coverCard(r,x)):'')+
 (!(shownCover&&cover.length)&&!(shownSwap&&r.swap.length)?`<div class="c empty-options"><b>${T2('No checked option in this view','در این بخش گزینهٔ بررسی‌شده‌ای پیدا نشد')}</b><p>${T2('Try the other option type, or review missing roster dates.','نوع دیگر پیشنهاد را ببینید، یا تاریخ‌های ناقص برنامه را بررسی کنید.')}</p></div>`:'')+
 (unique.length?`<details class="review-options-note"><summary>${unique.length} ${T2('items need roster review','مورد نیاز به بررسی برنامه')}</summary>${unique.map(x=>`<p><b>${bidi(x.m.name)}</b> · ${dateHTML(x.date||r.h.date)}<br>${swapReason(x)}</p>`).join('')}<button class="text-button" onclick="openRoster('${r.h.wp}')">${T2('Review digital roster','بررسی برنامهٔ دیجیتال')}</button></details>`:'')+
 (r.blocked.length?`<details class="blocked-options"><summary>${T2('Why direct cover is not offered','چرا پوشش مستقیم ممکن نیست؟')}</summary>${r.blocked.map(x=>`<p><b>${bidi(x.m.name)}</b> · ${swapReason(x)}</p>`).join('')}</details>`:'')+`</section>`}).join('')+`<details class="swap-rules"><summary>${T2('What is checked?','چه چیزهایی بررسی می‌شود؟')}</summary><p>${T2('Reciprocal exchanges use the same shift code, within 31 days, with confirmed off days on the receiving dates. Both resulting schedules are checked for night recovery, overlap and your minimum break. Missing or unreviewed dates cannot verify an exchange. Workplace approval is still yours to arrange.','تعویض دوطرفه برای شیفت هم‌نوع در فاصلهٔ ۳۱ روز است؛ هر دو نفر باید در روز دریافت شیفت تعطیل باشند. برنامهٔ جدید هر دو نفر از نظر تعطیل پس از شب، هم‌زمانی و حداقل استراحت بررسی می‌شود. روزهای ناقص یا بررسی‌نشده، تعویض را تأیید نمی‌کنند. توافق و تأیید محل کار را خودتان هماهنگ می‌کنید.')}</p><button class="text-button" onclick="editWp(tc.wp)">${T2('Workplace rules','قانون‌های محل کار')}</button></details>`;
}

const covV=w=>{const R=tc.res?coverCalc(w,tc.dates):null;if(tc.res)tc.res=R;const my=S.shifts.filter(h=>h.wp===w.id&&h.date>=iso(Date.now())&&h.segs.length).sort((a,b)=>a.date.localeCompare(b.date));
 if(!tc.cm)tc.cm=mfirst(new Date((my[0]?.date||iso(Date.now()))+'T00:00'));
 const first=mfirst(tc.cm),next=mfirst(new Date(first.getFullYear(),first.getMonth(),first.getDate()+32)),visible=my.filter(h=>h.date>=iso(first)&&h.date<iso(next));
 const list=visible.map(h=>`<button class="pk ${tc.dates.includes(h.id)?'on':''}" aria-pressed="${tc.dates.includes(h.id)}" onclick="togD('${h.id}')"><span>${dayLabel(h.date)}<small>${h.segs.map(g=>timeRange(g.s,g.e)).join(' · ')}</small></span><b class="code-tag">${codeHTML(h.text)}</b><span>${tc.dates.includes(h.id)?'✓':'+'}</span></button>`).join('');
 const grid=calendarDays(first).map(d=>{if(!d)return'<span></span>';const ds=iso(d),hs=my.filter(h=>h.date===ds),chosen=hs.some(h=>tc.dates.includes(h.id));return `<button class="cell cover-day ${chosen?'sel':''} ${ds===iso(Date.now())?'t':''} ${isWeekend(d)?'holiday':''}" ${hs.length?'':'disabled'} aria-pressed="${chosen}" aria-label="${esc(dlabel(ds))}" onclick="toggleCoverDay('${ds}')"><b class="day-number">${S.cal==='j'?jp(d).d:d.getDate()}</b>${hs.slice(0,2).map(h=>shiftMark(w,h.text)).join('')}${chosen?'<span class="selected-dot" aria-hidden="true"></span>':''}</button>`}).join('');
 const picker=`<section class="calendar-panel cover-picker"><div class="row month-heading"><button class="flip" onclick="moveCoverMonth(-1)" aria-label="${T2('Previous month','ماه قبل')}">‹</button><b>${first.toLocaleDateString(loc(),{month:'long',year:'numeric'})}</b><button class="text-button cover-view" onclick="tc.mode=tc.mode==='month'?'list':'month';render()" aria-label="${tc.mode==='month'?T2('List view','نمایش فهرست'):T2('Month view','نمایش ماه')}">${tc.mode==='month'?T2('List','فهرست'):T2('Month','ماه')}</button><button class="flip" onclick="moveCoverMonth(1)" aria-label="${T2('Next month','ماه بعد')}">›</button></div>${tc.mode==='month'?`<div class="grid cover-month">${weekdaysHTML()}${grid}</div>`:`<div class="cover-dates">${list||`<p class="mu">${T2('No work shifts this month.','این ماه شیفت کاری ثبت نشده است.')}</p>`}</div>`}<p class="cover-hint mu">${T2('Tap the shifts you want to hand over.','شیفت‌هایی را که می‌خواهید واگذار کنید انتخاب کنید.')}</p></section>`;
 const btn=`<button class="p cover-submit" onclick="coverGo()" ${tc.dates.length&&mates(w.id).length?'':'disabled'}>${T2('Find shift options','پیدا کردن پیشنهادها')}${tc.dates.length?` · ${tc.dates.length}`:''}</button>`;
 if(!R)return (tc.notice?`<div class="c saved-exchange" role="status"><b>✓ ${bidi(tc.notice)}</b><p>${T2('You can see the updated dates in Calendar and Digital roster.','تاریخ‌های جدید را در تقویم و برنامهٔ دیجیتال می‌بینید.')}</p></div>`:'')+`<p class="cover-intro">${T2('Choose a shift; we’ll look for cover and an exchange.','شیفتتان را انتخاب کنید؛ گزینه‌ها را با هم پیدا کنیم.')}</p>`+picker+btn+(mates(w.id).length?'':noMates());
 return `<details class="selection-details"><summary>${T2('Change selected shifts','تغییر شیفت‌های انتخاب‌شده')} (${tc.dates.length})</summary>${picker}${btn}</details>`+coverResults(R)};

function calendarDays(first){const key=d=>S.cal==='j'?jp(d).m:d.getMonth(),out=Array((first.getDay()-S.fdow+7)%7).fill(null);for(let d=first;key(d)===key(first);d=new Date(d.getFullYear(),d.getMonth(),d.getDate()+1))out.push(d);return out}
function weekdaysHTML(){return Array.from({length:7},(_,i)=>{const d=new Date(2024,0,7+(i+S.fdow)%7);return `<span class="weekday ${isWeekend(d)?'holiday':''}">${d.toLocaleDateString(loc(),{weekday:'short'})}</span>`}).join('')}
function moveCoverMonth(n){const d=mfirst(tc.cm);tc.cm=mfirst(n>0?new Date(d.getFullYear(),d.getMonth(),d.getDate()+32):new Date(d.getFullYear(),d.getMonth(),d.getDate()-1));tc.res=null;render()}
function toggleCoverDay(date){const hs=S.shifts.filter(h=>h.wp===tc.wp&&h.date===date&&h.segs.length),all=hs.every(h=>tc.dates.includes(h.id));for(const h of hs)tc.dates=all?tc.dates.filter(id=>id!==h.id):[...new Set([...tc.dates,h.id])];tc.res=null;render()}
const cmpV=w=>{const ms=mates(w.id),m=ms.find(x=>x.id===tc.mate),sel=`<select onchange="tc.mate=this.value;render()"><option value="">${T2('Choose a colleague','یه همکار انتخاب کن')}</option>${ms.map(x=>`<option value="${x.id}" ${x.id===tc.mate?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`;
  if(!m)return sel;const mine={};S.shifts.filter(h=>h.wp===w.id).forEach(h=>mine[h.date]=h.text);
  const both=[],a=[],b=[];for(const d of [...new Set([...Object.keys(mine),...Object.keys(m.cells)])].sort()){if((m.uns||[]).includes(d))continue;const x=mine[d]||'',y=m.cells[d]||'',xw=isWork(w,x),yw=isWork(w,y);if(xw&&yw)both.push([d,x,y]);else if(xw&&isOff(w,y))a.push([d,x]);else if(yw&&isOff(w,x))b.push([d,y])}
  const L=(t,arr,f)=>`<h1>${t} (${arr.length})</h1>`+(arr.length?`<div class="c">${arr.map(f).join('<br>')}</div>`:`<div class="c mu">—</div>`);
  return sel+((m.uns||[]).length?`<p class="c scan-notice">${T2('Dates needing scan review are excluded from this comparison.','تاریخ‌های نیازمند بررسی اسکن در این مقایسه نمایش داده نمی‌شوند.')}</p>`:'')+L(T2('Working together','با هم شیفت'),both,([d,x,y])=>`${dlabel(d)} · ${x} / ${y}`)+L(T2('I work, they are off','من شیفتم، همکارم آزاده'),a,([d,x])=>`${dlabel(d)} · ${x}`)+L(T2('They work, I am off','همکارم شیفته، من آزادم'),b,([d,y])=>`${dlabel(d)} · ${y}`)};
V.team=()=>{if(!S.wps.length)return`<div class="empty"><p class="mu">${T2('Add a workplace first.','ابتدا محل کارتان را وارد کنید.')}</p><button class="p" onclick="go('places')">Add workplace</button></div>`;
  const w=curWp();tc.wp=w.id;const ms=mates(w.id);
  if(tc.busy)return`<div class="c"><div class="pbar"><i></i></div><div id="prog" class="mu" style="margin-top:8px"></div><button class="p s" style="margin-top:10px" onclick="tc.cancel=1">${T2('Cancel','لغو')}</button></div>`;
  const wsel=S.wps.length>1?`<select onchange="tc.wp=this.value;tc.res=null;tc.dates=[];tc.month='';tc.cm=null;tc.mate='';render()">${S.wps.map(x=>`<option value="${x.id}" ${x.id===w.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:'';
  const tabs=[['cover',T2('Shift swap','تعویض شیفت')],['list',T2('Digital roster','برنامهٔ دیجیتال')],['cmp',T2('Compare','مقایسه')]].map(([k,l])=>`<button class="${tc.v===k?'on':''}" onclick="tc.v='${k}';render()">${l}</button>`).join('');
  return wsel+`<div class="seg team-tabs">${tabs}</div>`+(tc.v==='cover'?covV(w):!ms.length?noMates():tc.v==='cmp'?cmpV(w):digitalRoster(w))};
// Reads every other row of the last scanned sheet and stores them as colleagues (device only).
const cleanName=s=>(s||'').replace(/[\u200c\u200e\u200f|\[\]_]/g,' ').replace(/\s+/g,' ').trim();
async function readAll(){const w=S.wps.find(x=>x.id===sc.wp);if(!w||!sc.pages)return;tc.busy=true;tc.cancel=false;tc.v='list';tab='team';render();
  try{if(!sc.wk){const B=BASE();await loadScript(B+'tesseract.min.js');sc.wk=await Tesseract.createWorker('eng',1,{workerPath:B+'worker.min.js',corePath:B,langPath:B+'lang',gzip:true})}
    const wk=sc.wk,J=S.cal==='j',b0=J?fromJ(sc.y,sc.m,1):new Date(sc.y,sc.m-1,1),rows=sc.rows.filter((r,i)=>i!==sc.ri);
    await wk.setParameters({tessedit_pageseg_mode:'7',tessedit_char_whitelist:codeTokens(w)});
    for(let q=0;q<rows.length&&!tc.cancel;q++){const r=rows[q];usePage(r.pi);const V=sc.vl,cells={},uns=[];P(T2('Reading colleague ','خوندن همکار ')+(q+1)+'/'+rows.length,q/rows.length);
      for(let i=0;i<V.length-1;i++){const day=sc.dayAt(i);if(day<1||day>31||i===sc.nameCol)continue;const d=new Date(b0.getFullYear(),b0.getMonth(),b0.getDate()+day-1);if(!(J?jp(d).m===sc.m:d.getMonth()===sc.m-1))continue;
        const result=await recognizeShift(w,wk,...cellBounds(V[i],r.y0,V[i+1],r.y1)),t=result.text;
        if(sc.guess||result.c<80||result.uncertain||!t||!parse(w,t))uns.push(iso(d));
        if(t&&parse(w,t))cells[iso(d)]=t;}
      const name=cleanName(r.nm),matches=(S.mates||[]).filter(m=>m.wp===w.id&&nn(m.name)===nn(name)),ex=name&&matches.length===1?matches[0]:null;
      const meta={img:r.img,rawName:r.rawName||r.nm,nameFeature:r.nameFeature};
      if(ex){Object.assign(ex.cells,cells);ex.uns=[...(ex.uns||[]).filter(x=>!(x in cells)),...uns];Object.assign(ex,meta)}else(S.mates=S.mates||[]).push({id:'m'+Date.now()+q,wp:w.id,name:name||'#'+(q+1),...meta,cells,uns})}

    save()}catch(e){alert('Error: '+e.message)}
  tc.busy=false;await killWk();render()}


let roster={wp:'',cm:null,page:0,wide:false,search:'',returnTab:'agenda'};
function openRoster(id){if(id)roster.wp=id;roster.returnTab=['agenda','team','today'].includes(tab)?tab:'agenda';roster.cm=mfirst(cm);roster.page=0;go('roster')}
V.roster=()=>{if(!S.wps.length)return noMates();const w=S.wps.find(w=>w.id===roster.wp)||curWp();roster.wp=w.id;return (S.wps.length>1?`<select aria-label="${T2('Workplace','محل کار')}" onchange="roster.wp=this.value;roster.cm=null;roster.page=0;render()">${S.wps.map(x=>`<option value="${x.id}" ${w.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:'')+digitalRoster(w)};
function digitalRoster(w){if(!roster.cm){const latest=S.shifts.filter(h=>h.wp===w.id).sort((a,b)=>a.date.localeCompare(b.date))[0];roster.cm=mfirst(new Date((latest?.date||iso(Date.now()))+'T00:00'))}const first=mfirst(roster.cm),days=calendarDays(first).filter(Boolean);roster.page=Math.min(roster.page,Math.floor((days.length-1)/7));
 const shown=roster.wide?days:days.slice(roster.page*7,roster.page*7+7),mine=Object.fromEntries(S.shifts.filter(h=>h.wp===w.id).map(h=>[h.date,h])),ms=mates(w.id).filter(m=>!roster.search||nn(m.name).includes(nn(roster.search))),rows=[{id:'self',name:S.myname||T2('You','شما'),cells:Object.fromEntries(Object.values(mine).map(h=>[h.date,h.text])),uns:Object.values(mine).filter(h=>h.review).map(h=>h.date)},...ms];
 const table=`<div class="roster-scroll ${roster.wide?'wide':''}" tabindex="0" aria-label="${T2('Digital roster table','جدول دیجیتال برنامه')}"><table class="roster-table"><thead><tr><th scope="col">${T2('Name','نام')}</th>${shown.map(d=>`<th scope="col" class="${iso(d)===iso(Date.now())?'roster-today':''}"><b>${S.cal==='j'?jp(d).d:d.getDate()}</b><small>${d.toLocaleDateString(loc(),{weekday:'short'})}</small></th>`).join('')}</tr></thead><tbody>${rows.map(m=>`<tr class="${m.id==='self'?'self-row':''}"><th scope="row">${m.id==='self'?`<b>${bidi(m.name)}</b><small>${T2('Your shifts','برنامهٔ شما')}</small>`:`<button class="roster-name" onclick="renMate('${m.id}')">${bidi(m.name)}</button>`}</th>${shown.map(d=>{const ds=iso(d),t=m.cells[ds],u=(m.uns||[]).includes(ds);return `<td class="${u?'uncertain-cell':''} ${ds===iso(Date.now())?'roster-today':''}"><button class="roster-cell" onclick="${m.id==='self'?mine[ds]?`editShift('${mine[ds].id}')`:`addRosterShift('${w.id}','${ds}')`:`editMateCell('${m.id}','${ds}')`}" aria-label="${esc(m.name+' '+dateText(ds)+' '+(t||T2('Unknown','نامشخص')))}">${t?shiftMark(w,t):'<span class="unknown-mark">?</span>'}${u?'<span class="review-dot" aria-label="Needs review">•</span>':''}</button></td>`}).join('')}</tr>`).join('')}</tbody></table></div>`;
 return `<section class="c digital-sheet"><div class="row month-heading"><button class="flip" onclick="moveRosterMonth(-1)" aria-label="${T2('Previous month','ماه قبل')}">‹</button><b>${first.toLocaleDateString(loc(),{month:'long',year:'numeric'})}</b><button class="flip" onclick="moveRosterMonth(1)" aria-label="${T2('Next month','ماه بعد')}">›</button></div><input class="roster-search" aria-label="${T2('Search colleague names','جستجوی نام همکار')}" placeholder="${T2('Search colleague names','جستجوی نام همکار')}" value="${esc(roster.search)}" oninput="filterRoster(this.value)"><div class="roster-range"><button class="icon-button flip" ${roster.page===0||roster.wide?'disabled':''} onclick="roster.page--;render()" aria-label="${T2('Previous days','روزهای قبل')}">‹</button><span>${dateHTML(shown[0])} – ${dateHTML(shown.at(-1))}</span><button class="icon-button flip" ${(roster.page+1)*7>=days.length||roster.wide?'disabled':''} onclick="roster.page++;render()" aria-label="${T2('Next days','روزهای بعد')}">›</button></div>${table}<div class="roster-actions"><button class="text-button" onclick="roster.wide=!roster.wide;render()">${roster.wide?T2('Fit screen','نمایش متناسب با صفحه'):T2('Whole month','نمایش کل ماه')}</button><button class="text-button" onclick="editWp('${w.id}',true)">${T2('Symbol meanings','معنی علامت‌ها')}</button></div><p class="roster-note">${T2('Tap a cell to edit. ? means unknown, not off; dotted cells need review.','برای ویرایش روی خانه بزنید. ؟ یعنی نامشخص، نه تعطیل؛ نقطه یعنی نیازمند بررسی.')}${roster.wide?T2(' Swipe the table to see all dates.',' برای دیدن همهٔ تاریخ‌ها، جدول را به طرفین بکشید.'):''}</p></section>`+(ms.length?'':noMates())}
function filterRoster(value){roster.search=value;render();const el=$('.roster-search');el?.focus();el?.setSelectionRange(value.length,value.length)}
function moveRosterMonth(n){const d=mfirst(roster.cm);roster.cm=mfirst(n>0?new Date(d.getFullYear(),d.getMonth(),d.getDate()+32):new Date(d.getFullYear(),d.getMonth(),d.getDate()-1));roster.page=0;render()}
function editMateCell(id,date){const m=S.mates.find(m=>m.id===id);if(!m)return;const w=wp(m.wp),text=m.cells[date]||'';dlg(`<h3>${T2('Edit colleague shift','ویرایش شیفت همکار')}</h3><p>${bidi(m.name)} · ${dateHTML(date)}</p><div class="shift-keys">${presetCodes(w).map(c=>`<button class="shift-key" onclick="$('#mate-code').value=${esc(JSON.stringify(c.code))}"><bdi dir="ltr">${esc(c.code)}</bdi><small>${esc(c.label)}</small></button>`).join('')}</div><input id="mate-code" dir="ltr" autocapitalize="off" value="${esc(canonicalShift(w,text))}" aria-label="${T2('Shift symbol','علامت شیفت')}"><div class="dialog-actions"><button class="p" onclick="saveMateCell('${id}','${date}')">Save</button><button class="p s" onclick="closeDialog()">${T2('Cancel','لغو')}</button></div><button class="text-button" onclick="clearMateCell('${id}','${date}')">${T2('Mark as unknown','ثبت به‌عنوان نامشخص')}</button>`)}
function saveMateCell(id,date){const m=S.mates.find(m=>m.id===id),t=canonicalShift(wp(m.wp),nrm($('#mate-code').value.trim()));if(!parse(wp(m.wp),t))return alert(T2('Define this symbol first.','ابتدا معنی این علامت را تعریف کنید.'));m.cells[date]=t;m.uns=(m.uns||[]).filter(d=>d!==date);tc.res=null;save();closeDialog();render()}
function clearMateCell(id,date){const m=S.mates.find(m=>m.id===id);delete m.cells[date];m.uns=(m.uns||[]).filter(d=>d!==date);tc.res=null;save();closeDialog();render()}
function addRosterShift(id,date){addShift(date);$('#fw').value=id;chips()}
function editDayShift(){const hs=S.shifts.filter(h=>h.date===sel);if(hs.length===1)editShift(hs[0].id);else addShift(sel)}

function loadingProgress(value,text){const screen=$('#loading-screen');if(!screen)return;screen.style.setProperty('--loading-progress',value+'%');if(text)$('#loading-status').textContent=text}
function finishLoading(){const screen=$('#loading-screen');if(!screen)return;setTimeout(()=>{loadingProgress(100,'آماده‌ایم؛ برویم سراغ روزهای شما');setTimeout(()=>{screen.classList.add('ready');setTimeout(()=>screen.remove(),300)},950)},Math.max(0,1100-(Date.now()-bootStarted)))}

(async()=>{try{loadingProgress(12,'داریم برنامه‌تان را باز می‌کنیم…');const L=await load()||{};if(L.wps&&!L.ver){L.lang='fa';L.cal='j';L.ver=3}S={...S,...L};loadingProgress(70,'شیفت‌ها و تنظیماتتان را سر جای خود می‌گذاریم…');normalizeSavedOff();sel=iso(Date.now());cm=mfirst(new Date());render();finishLoading();if('serviceWorker'in navigator){navigator.serviceWorker.register('sw.js').catch(()=>{});if(navigator.serviceWorker.controller)navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload())}}catch(e){const screen=$('#loading-screen');if(screen){$('#loading-status').textContent='برنامهٔ ذخیره‌شده باز نشد. دوباره تلاش کنید.';screen.querySelector('.loading-retry').hidden=false;screen.classList.add('load-error')}}})();
setInterval(()=>tab==='today'&&!$('#dlg').open&&render(),60000);
